+            case 3:
+                if (metadata == null) {
+                    metadata = new HashMap<>(1);
+                } else {
+                    metadata = new HashMap<>(instance.getMetadata());
+                }
+                metadata.put(randomAlphaOfLength(15), randomInt());
+                break;
+            case 4:
+                complete = !complete;
+                break;
+            case 5:
+                includeSorts = !includeSorts;
+                break;
