+        SortOrder sortOrder = SortOrder.ASC;
+        List<InternalGeoLine> geoLines = new ArrayList<>();
+        for (int i = 0; i < numLines; i++) {
+            geoLines.add(randomLine(sortOrder, maxLength, ((double) i) / numLines));
