+        doFirst {
+            logger.info("Shutting down ${fixture.name} with pid ${pid}")
+        }
+
+        if (Os.isFamily(Os.FAMILY_WINDOWS)) {
+            executable = 'Taskkill'
+            args('/PID', pid, '/F')
+        } else {
+            executable = 'kill'
+            args('-9', pid)
+        }
+        doLast {
+            fileSystemOperations.delete {
+                it.delete(fixture.pidFile)
+            }
+        }
+        this.fixture = fixture
+    }
+}
